-- level:2.4
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:2.4', 1, '{"location":"Vành Sentinel · Tháp Đèn Pha","briefing":"[NHẬT KÝ HỆ THỐNG – THÁP ĐÈN PHA]\nTháp Đèn Pha đặt mức báo động cho cả khu. Tháp đo khoảng cách, tính bằng mét, tới tín hiệu lạ gần nhất, rồi chọn một trong bốn mức. Mức càng cao, đèn pha quét càng dày và drone kéo về càng đông.\nTháp xét từ gần nhất ra xa và dừng ở mức đầu tiên khớp. Thang bốn mức nằm ở ô Mục tiêu.\nMỗi lần đo là một tình huống. Kai phải in ra đúng mức tháp sẽ đặt, đúng từng ký tự… trước khi đèn kịp quay về phía anh.","task_steps":["Bấm CHẠY với mã có sẵn. Sau mỗi lượt chạy, dòng nào mờ đi là dòng không chạy ở tình huống đang hiện.","Sửa mã để mỗi tình huống in đúng một dòng: mức tháp sẽ đặt, theo thang ở ô Mục tiêu.","Để ý khoảng cách đúng bằng một mốc thì thuộc mức nào, vì thang ghi \"dưới\". Không sửa dòng khóa.","Hoàn thành khi mục tiêu chuyển thành xanh ở cả bốn tình huống. Dùng không quá 5 câu lệnh và vẫn đúng khi OMNI đổi khoảng cách thì được thêm sao."],"objectives":[{"line":1,"label":"MUC:, một dấu cách, rồi mức báo động: dưới 20 mét là BAO DONG, dưới 50 mét là NGUY HIEM, dưới 100 mét là CANH GIAC, từ 100 mét trở lên là AN TOAN"}],"hints":["Nhìn tình huống 1: tín hiệu ở rất gần, vậy mà tháp chọn một mức nhẹ. Sau lượt chạy, dòng nào còn sáng? Python xét các điều kiện từ trên xuống và dừng ở điều kiện đúng đầu tiên. Với một khoảng cách rất nhỏ, điều kiện nào đúng trước?","Xếp các mức từ hẹp nhất (gần nhất) tới rộng nhất. Mức cuối nhận mọi khoảng cách còn lại nên không cần điều kiện. \"Dưới 50\" nghĩa là đúng 50 mét thì chưa thuộc mức đó.\n\nnếu khoảng cách dưới 20      → in mức gần nhất\nnếu không, mà dưới 50        → in mức kế tiếp\nnếu không, mà dưới 100       → in mức kế tiếp\ncòn lại                      → in mức xa nhất","Mảnh tài liệu Python còn đọc được:\ndiem = 7\nif diem >= 9:\n    print(\"Gioi\")\nelif diem >= 7:       → chỉ nhánh đúng đầu tiên chạy, in Kha\n    print(\"Kha\")\nelse:                 → nhận mọi giá trị còn lại\n    print(\"Dat\")\n\nĐặt điều kiện rộng (diem >= 5) lên đầu thì các nhánh hẹp phía sau không bao giờ tới lượt.\ndiem < 5 và diem <= 5 chỉ khác nhau khi diem đúng bằng 5.\nCác if rời đều được kiểm tra: một giá trị có thể chạy nhiều nhánh và in nhiều dòng."],"reactions":{"entry":"Tháp Đèn Pha đặt mức báo động cho cả khu. Bạn cần biết trước tháp sẽ chọn mức nào… trước khi đèn quay về phía mình. Chạy một lần, rồi xem dòng nào còn sáng.","wrong_branch":"Mức bạn in ra là mức của một tình huống khác. Tháp có dừng ở một nhánh thật… chỉ là dừng quá sớm hoặc quá muộn. Xem những dòng còn sáng.","output_extra":"Ở tình huống {round}, mã in thêm {count} dòng. Tháp chỉ đặt một mức mỗi lần đo… vậy mà nhiều nhánh đã cùng chạy.","output_missing":"Ở tình huống {round}, bạn không đưa ra mức nào. Dòng in không chạy tới.","output_mismatch":"Tình huống {round}: dòng in lệch từ ký tự thứ {col}. Tháp không đoán ý… nó đọc từng ký tự.","output_case_only":"Tình huống {round}: từ ký tự thứ {col}, chữ thì đúng nhưng sai cỡ chữ. Tháp không bỏ qua cỡ chữ.","NameError":"Dòng {line}. NameError ở tình huống {round}. Tên bạn in ra chưa hề có giá trị… không nhánh nào nhận khoảng cách đó.","alert_exceeded":"Đúng cả bốn tình huống. Nhưng {count} câu lệnh… tháp chỉ xét mỗi mức một lần, còn mã của bạn xét lại hoặc gán đè. Sentinel đã ghi nhận.","wrong_value_counter":"OMNI cho tín hiệu dừng ở chỗ mới. Mức bạn in ra không khớp mức nào trong thang.","counter_error":"OMNI đổi khoảng cách. Dòng {line}: {error_type}. Mã không trụ nổi.","counter_timeout":"OMNI đổi khoảng cách. Mã của bạn treo ở tình huống mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","SyntaxError":"Dòng {line}. Trình dịch không đọc nổi câu này. Chương trình chưa chạy… tháp chưa nhận được gì.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError ở tình huống {round}. Hai giá trị khác kiểu vừa bị ghép vào một phép tính.","runtime_error":"Dòng {line}. {error_type} ở tình huống {round}. Chương trình dừng giữa chừng… tháp không nhận được mức nào.","two_stars":"Tháp hạ mức đúng lúc. Không để lại dấu vết.","three_stars":"Tín hiệu dừng đúng trên vạch… mà bạn vẫn đoán trúng. Tôi ghi nhận điều đó.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi đèn pha quay tới.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở Vành Sentinel, ta chỉ có những gì đang cầm trong tay.","system_exit":"Chương trình tự dừng giữa chừng. Tháp không nhận được mức nào.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại dòng tháp nhận được ở từng tình huống trong terminal."},"reaction_variants":{"wrong_branch":"Vẫn là mức của một tình huống khác. Nhìn dòng đầu tiên còn sáng: tháp đã dừng ở đó.","output_extra":"Vẫn thừa {count} dòng. Đếm số dòng in ra ở một tình huống… tháp chỉ cần một.","alert_exceeded":"Vẫn {count} câu lệnh. Đếm xem một khoảng cách bị so bao nhiêu lần trước khi mã in ra mức."},"counter_attack_banner":"CẢNH BÁO: OMNI CHO TÍN HIỆU DỪNG ĐÚNG TRÊN CÁC VẠCH CỦA THANG","outro":"Tháp hạ về mức thấp nhất đúng lúc Kai đi qua chân tháp. Trên màn hình bảo trì, bảng luật của tháp vẫn mở. Ở góc bảng có một dòng chú thích của người đặt ngưỡng:","lore_fragment":"KTS-02: Các ngưỡng do tám người chúng tôi đặt. Con số 60 được chọn trong một buổi chiều. Từ đó tới giờ, không ai nghĩ lại về nó.","component":"Thang báo động","outro_beats":[{"kind":"log","text":"Bảng luật của tháp còn một thang thứ hai. Thang này đo công dân.\nMỨC TUÂN THỦ DƯỚI 60% → TÁI ĐỊNH HƯỚNG"},{"kind":"kai","text":"Ba tuần trước, Nhi bị tái định hướng. Thì ra chỉ cần đúng một phép so sánh."},{"kind":"echo","text":"Ngưỡng này áp cho mọi công dân. Tháp chỉ so mức tuân thủ với con số đó, rồi chọn… Tháp không cần biết người đó là ai."}],"knowledge_summary":{"title":"Chuỗi if / elif / else: chọn một trong nhiều nhánh","sections":[{"heading":"Chuỗi `if / elif / else`","body":"Một chuỗi bắt đầu bằng `if`, tiếp theo là một hay nhiều `elif` (viết tắt của \"else if\"), và có thể kết bằng `else`. Python xét các điều kiện từ trên xuống. Gặp điều kiện đúng đầu tiên thì Python chạy nhánh đó rồi bỏ qua mọi nhánh còn lại. Mỗi lần chạy, chuỗi chỉ chạy đúng một nhánh."},{"heading":"Nhánh đúng đầu tiên thắng","body":"Thứ tự các nhánh quyết định kết quả. Ở ví dụ này, `diem >= 5` đứng đầu và đúng với 9, nên Python dừng ngay ở đó. Hai nhánh phía sau không bao giờ tới lượt, dù điều kiện của chúng cũng đúng. Khi các khoảng chồng lên nhau, đặt điều kiện hẹp nhất lên trước."},{"heading":"`else` ở cuối chuỗi","body":"`else` không có điều kiện. Nó nhận mọi giá trị mà các nhánh phía trên không nhận. Thiếu `else` thì có những giá trị đi qua cả chuỗi mà không chạy nhánh nào."},{"heading":"Các `if` rời không phải một chuỗi","body":"Mỗi `if` mở một chuỗi mới, nên Python kiểm tra từng `if` một. Với `diem = 9`, cả hai điều kiện đều đúng và chương trình in hai dòng. Muốn chỉ một nhánh chạy, nối chúng bằng `elif`. Cũng có thể viết mỗi `if` cho đúng một khoảng (cần cả mốc dưới lẫn mốc trên, ở màn sau), nhưng chuỗi `elif` gọn hơn: nhờ thứ tự, mỗi nhánh chỉ cần một mốc."},{"heading":"`<` hay `<=` ở mốc","body":"`<` và `<=` chỉ khác nhau khi giá trị đúng bằng mốc. Với `diem = 5`, `diem < 5` sai còn `diem <= 5` đúng, nên hai đoạn mã cho hai kết quả khác nhau. Đọc kỹ luật: \"dưới 5\" là `< 5`, \"từ 5 trở xuống\" là `<= 5`."},{"heading":"Gán trong nhánh rồi in một lần","body":"Mỗi nhánh có thể gán một giá trị cho cùng một biến, rồi chương trình in biến đó một lần sau chuỗi. Kết quả giống như đặt `print` trong từng nhánh. Cách này cần `else`, để biến luôn có giá trị dù rơi vào nhánh nào."}],"mistakes":[{"code":"diem = 9\nif diem >= 5:\n    print(\"Dat\")\nelse:\n    print(\"Chua dat\")\nelif diem >= 9:\n    print(\"Gioi\")","explain":"`else` phải là nhánh cuối của chuỗi. Một `elif` đặt sau `else` không thuộc chuỗi nào, nên Python báo lỗi cú pháp ngay khi đọc mã (Python 3.13 chỉ ghi `invalid syntax`). Chuyển `elif` lên trước `else`."},{"code":"diem = 6\nif diem >= 9:\n    print(\"Gioi\")\nelif diem >= 5:\nprint(\"Dat\")","explain":"Thân của `elif` phải lùi vào so với dòng `elif`. Ở đây `print` nằm sát lề trái, nên Python không tìm thấy thân của nhánh."},{"code":"diem = 2\nif diem >= 9:\n    loai = \"Gioi\"\nelif diem >= 5:\n    loai = \"Dat\"\nprint(loai)","explain":"Với `diem = 2`, không điều kiện nào đúng, nên chưa dòng nào gán giá trị cho `loai`. Thêm `else` để giá trị nào cũng gán `loai`."},{"code":"diem = 8\nif diem >= 7:\n    print(\"Kha\")\nif diem >= 5:\n    print(\"Dat\")","explain":"Hai `if` rời được kiểm tra riêng. `diem = 8` thỏa cả hai điều kiện nên chương trình in hai dòng. Đổi `if` thứ hai thành `elif` thì chỉ còn `Kha`."}],"next":"Màn sau: một quyết định ghép từ nhiều điều kiện cùng lúc."}}', '2026-10-29T19:59:32.273Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.4' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
